JP_CHARACTER_UPDATES.forEach(u=>{const c=CHARACTERS.find(x=>x.nameKo===u.oldName||x.nameKo===u.nameKo);if(!c)return;const oldName=c.nameKo;c.nameKo=u.nameKo;c.nameCn=u.nameCn;c.status=u.status;c.source=u.source;c.released=false;c.cardId=u.cardId;c.aliases=[...new Set([...(c.aliases||[]),oldName,u.nameKo,u.nameCn])];c.detail=Object.assign({},c.detail||{},u.detail);});

const JP_PREVIOUS_STATUS_CLASS=statusClass;
const JP_SKILL_DETAIL_CORRECTIONS={
 '리리안':{
  normalSkill:'적 1명에게 현재 공격력에 비례한 피해를 주고 MP 5pt를 획득합니다. 마리나와 함께 출전하면 MP를 추가로 1pt 획득합니다.',
  combatSkill:'MP 30pt를 소모해 암영혈계를 발동합니다. 대상 1명을 3회 공격하며, 암영혈계를 2회 발동할 때마다 암영서 페이지를 1장 획득합니다. 페이지 중첩에 따라 치명타 피해와 스킬 피해가 증가하고 최대 중첩 시 암영종장을 획득합니다.',
  feverSkill:'적 1명에게 큰 피해를 주고 기절을 부여합니다. 보유한 암영서 페이지와 암영종장 효과에 따라 피해가 강화됩니다.'},
 '마리나':{
  normalSkill:'적 1명에게 현재 공격력에 비례한 피해를 줍니다.',
  combatSkill:'전투 시작 후 자신을 제외한 아군과 적에게 혈월을 부여합니다. 마리나는 매초 최대 HP를 소모해 혈월치를 얻고, 혈월치 10pt마다 혈월 레벨이 1단계 상승합니다. 혈월은 아군의 기초 공격력을 높이고 적의 기초 공격력을 낮춥니다.',
  feverSkill:'일정 시간마다 가장 가까운 적 1명에게 피해를 줍니다. 혈월 레벨이 오를 때마다 피해 배율이 증가하며, 리리안과 함께 출전하면 레벨당 추가 피해 배율이 더 증가합니다.'},
 '사를라':{
  normalSkill:'적 1명에게 현재 공격력에 비례한 피해를 주고 혈계의 각인을 획득합니다.',
  combatSkill:'10초마다 자신의 최대 HP 일부를 소모하고 가장 가까운 적 3명에게 피해를 줍니다. 혈계의 각인을 보유한 경우 각인을 모두 소모해 중첩당 피해 배율을 높이고 수속성 지속 피해와 방어력 감소를 부여합니다.',
  feverSkill:'총공격 단계 진입 시 자신의 HP를 소모하고 아군 전체의 속성 상성 유리 피해를 증가시킵니다. 가장 가까운 적들에게 공격을 가하며 혈계의 각인 소모량에 따라 피해가 강화됩니다.'}
};
Object.entries(JP_SKILL_DETAIL_CORRECTIONS).forEach(([name,v])=>{const c=CHARACTERS.find(x=>x.nameKo===name);if(!c)return;Object.assign(c.detail,v);c.detail.skillSummary=`일반 스킬\n${v.normalSkill}\n\n전투 스킬 · ${c.detail.combatSkillName}\n${v.combatSkill}\n\n피버 스킬 · ${c.detail.feverSkillName}\n${v.feverSkill}`;for(const kind of ['normal','combat','fever']){const base=v[`${kind}Skill`];const audit=CLIENT_SKILL_AUDIT[name]?.[kind];if(audit) audit.descriptions=(audit.descriptions||[]).map((_,i)=>{const rate=CLIENT_GROWTH_DATA[name]?.skills?.[kind]?.[i]?.damageRate||0;return (rate?`피해 배율: ${rate}%\n`:'')+base;});}});
statusClass=function(s){return (s||'').includes('일본 서버 기준')?'warn':JP_PREVIOUS_STATUS_CLASS(s);};
selectedIndex=-1;
if(activeTab==='badge') renderBadge(); else if(activeTab==='skill') renderSkill(); else if(activeTab.startsWith('tier')) renderTier(); else if(activeTab==='gacha') renderGacha();
